import json
import sys

def resolver(datos):
    return round(datos["precio"] * datos["cantidad"] * (1-datos["descuento"]), 2)

if __name__ == "__main__":
    datos = json.loads(sys.stdin.read())
    print(json.dumps(resolver(datos), ensure_ascii=False, separators=(",", ":")))

