import json
import sys

def resolver(datos):
    if any(p["precio"] < 0 or p["cantidad"] < 0 for p in datos["productos"]):
        return {"error": "datos invalidos"}
    return {"total": round(sum(p["precio"] * p["cantidad"] for p in datos["productos"]), 2)}

if __name__ == "__main__":
    datos = json.loads(sys.stdin.read())
    print(json.dumps(resolver(datos), ensure_ascii=False, separators=(",", ":")))

